  transition: opacity 0.2s;
}
.promo-banner .close-btn:hover { opacity: 1; }
.promo-banner.hidden { display: none; }

/* ─── Header ─── */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
