  line-height: 1.6;
  margin-bottom: 24px;
  max-width: 500px;
}
.hero-stats {
  display: flex;
  gap: 24px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}
.hero-stat {
  font-size: 14px;
  color: rgba(255,255,255,0.6);
}
.hero-stat strong { color: var(--white); font-weight: 700; }
